class BoundingCircle {

	constructor(r, weight) {
		this.r = r
		this.w = weight 
		this.pos = { x : w / 2, y : h / 2 }
		this.noiseMax = 1
		this.context = createGraphics(2 * r + w * 0.1, 2 * r + h * 0.1) 
	}

	render() {
		this.context.fill(black)

		this.context.beginShape()
		let polarOff = 3000
		for (let theta = 0; theta < TAU; theta += 0.01) {
			let xoff = map(polarOff + cos(theta), -1, 1, 0, this.noiseMax)
			let yoff = map(polarOff + sin(theta), -1, 1, 0, this.noiseMax)
			let radius = this.r + noise(1000 + xoff, 1000 + yoff) * this.r * 0.1
			let x = radius * cos(theta) + this.context.width / 2
			let y = radius * sin(theta) + this.context.height / 2
			this.context.vertex(x, y)
			xoff += 0.01
		}
		this.context.endShape()

		this.context.erase()
		polarOff = 5000
		this.context.beginShape()
		for (let theta = 0; theta < TAU; theta += 0.01) {
			let xoff = map(polarOff + cos(theta), -1, 1, 0, this.noiseMax)
			let yoff = map(polarOff + sin(theta), -1, 1, 0, this.noiseMax)
			let radius = this.r - this.w + noise(1000 + xoff, 1000 + yoff) * this.r * 0.1
			let x = radius * cos(theta) + this.context.width / 2
			let y = radius * sin(theta) + this.context.height / 2
			this.context.vertex(x, y)
			xoff += 0.01
		}
		this.context.endShape()
		this.context.noErase()
	}

	draw() {
		image(this.context, this.pos.x, this.pos.y)
	}
}


class Ray {
	constructor(angle, col) {
		this.angle = angle
		this.color = color(20, 45, 70)
		this.verteces = []
		this.cx = w / 2 + random([-1, 1]) * random(w * 0.15)
		this.cy = h / 2 + random([-1, 1]) * random(w * 0.15)
		this.color = col
	}

	init() {
		let x1 = this.cx
		let y1 = -random(100, 200)
		let x2 = x1, y2 = h * 1.5 + random(100, 200)
		let r = dist(x1, y1, x2, y2) 
        let theta = atan2(y2 - y1, x2 - x1)
        let tangentAngle = theta + random([-1, 1]) * random(radians(5), radians(7)) // Change the angle
        let d1x= x1 + r * cos(tangentAngle)
        let d1y = y1 + r * sin(tangentAngle)
        let d2x= x1 + r * cos(PI - tangentAngle)
        let d2y = y1 + r * sin(PI - tangentAngle)

		this.verteces = [
			{ x: x1, y : y1 },
			{ x: d1x, y : d1y },
			{ x: d2x, y : d2y },
		]
	}

	draw() {
		// Just a huge triangle
		push()
		noStroke()
		fill(this.color)
		translate(this.cx, this.cy)
		rotate(this.angle)
		translate(-this.cx, -this.cy)
		beginShape()
		for (let i = 0; i < 3; i++) {
			vertex(this.verteces[i].x, this.verteces[i].y)
		}
		endShape(CLOSE)
		pop()
	}
}


class Circle {

	constructor(x, y) {
		this.cx = x
		this.cy = y
		this.x = this.cx
		this.y = this.cy
		this.hasBorder = random() < 0.5 ? true : false
		this.d = dist(w / 2, h / 2, x, y)
		this.randOff = random(10000)
		this.noiseMax = 2
		this.perlinOff = 0.005 // has to be an absolute value
		this.polarAngle = 0
		this.polarPhase = random(TAU)
		this.noiseScale = random(20, 70)

		let rLowerLim = map(this.d, 0, boundary.r * 0.8, 70, 10)
		let rUpperLim = map(this.d, 0, boundary.r * 0.8, 250, 25)
		this.r = random(rLowerLim, rUpperLim) / 2

		if (this.hasBorder)
			this.borderWeight = random([1, 2, 2, 3, 3, 3, 4, 4, 6, 7])
		if (random() < 0.4 && this.hasBorder && this.borderWeight <= 3) {
			this.hasCenterPoint = true
			this.centerWeight = random(this.r * 0.25, this.r * 0.4)
		}
		this.color = random(pal)

	}

	draw() {
		push()
		// noFill()
		fill(this.color)
		stroke(black)
		strokeWeight(this.borderWeight)
		this.squigglyCircle(this.x, this.y, this.r)
		if (this.hasCenterPoint) {
			fill(black)
			this.squigglyCircle(this.x, this.y, this.centerWeight)
		}
		pop()
	}

	squigglyCircle(x_, y_, rad) {
		beginShape()
		let polarOff = this.randOff + 3000
		for (let theta = 0; theta < TAU; theta += 0.01) {
			let xoff = map(polarOff + cos(theta), -1, 1, 0, this.noiseMax)
			let yoff = map(polarOff + sin(theta), -1, 1, 0, this.noiseMax)
			let radius = rad + noise(1000 + xoff, 1000 + yoff) * rad * 0.1
			let x = radius * cos(theta) + x_
			let y = radius * sin(theta) + y_
			vertex(x, y)
			xoff += 0.01
		}
		endShape()

	}

	update() {
		let polarOff = this.randOff + 3000
		let xoff = this.randOff + map(polarOff + cos(this.polarPhase + this.polarAngle), -1, 1, 0, 2)
		let yoff = this.randOff + map(polarOff + sin(this.polarPhase + this.polarAngle), -1, 1, 0, 2)

		this.x = this.cx + noise(xoff, yoff) * this.noiseScale
		this.y = this.cy + noise(3000 + xoff, 3000 + yoff) * this.noiseScale

		this.polarAngle += this.perlinOff
		if (this.polarAngle >= TAU) this.polarAngle -= TAU
	}
}


class Line {

	constructor(x, y) {
		this.x = x
		this.y = y
		this.theta = random([1, -1]) * random(PI / 2)
		let d;
		do {
			this.x0 = random(h * 0.8) * cos(this.theta) + this.x
			this.y0 = random(h * 0.8) * sin(this.theta) + this.y

			d = dist(this.x0, this.y0, w / 2, h / 2)	
		} while (d > boundary.r * 0.8);
		do {
			this.x1 = - random(h * 0.8) * cos(this.theta) + this.x
			this.y1 = - random(h * 0.8) * sin(this.theta) + this.y

			d = dist(this.x1, this.y1, w / 2, h / 2)	
		} while (d > boundary.r * 0.8)

		this.weight = random([1, 2, 2, 3])
	}

	draw() {
		push()
		strokeWeight(this.weight)
		stroke(black)
		line(this.x0, this.y0, this.x1, this.y1)
		pop()
	}
}

class Sqiggly {

	constructor(x, y) {
		this.x = x
		this.y = y

		this.x0 = x; this.y0 = this.y - random(5, 20)
		this.x1 = x; this.y1 = this.y + random(5, 20)
		this.a = random(0.5, 1.5)
		this.b = random(0.5, 1.5)
		this.phi = random([-1, 1]) * random(PI / 2)
		this.d = dist(this.x0, this.y0, this.x1, this.y1)
		this.scale = random(1, 1.5)
		this.angle = random(PI / 2)
		this.weight = random([1, 2, 3])
	}

	draw() {
		push()
		translate(this.x, this.y)
		rotate(this.angle)
		scale(this.scale)
		translate(-this.x, -this.y)
		strokeWeight(this.weight)
		stroke(black)
		beginShape()
		for (let i = 0; i < this.d; i += 1) {
			let x = this.x0 + i
			let y = this.y0 + this.a * sin(this.phi + this.b * x)
			vertex(x, y)
		}
		endShape()
		pop()
	}
}


let boundary, circles, numCircles, lines, numLines, sqiggs, numSquiggs
let black = "#10060D"
function setup() {
    l = min(windowHeight, windowWidth)
    createCanvas(w = l, h = l)
	bgBuff = createGraphics(w, h)

    bg = color("#ECDBD1")

	bgBuff.background(bg)
	gorillaGrain(20, bgBuff)


	// // noLoop() removed for animation// For now
	imageMode(CENTER)

	stroke(black)

	// Objects
	boundary = new BoundingCircle(l * 0.45, l * 0.05)
	boundary.render()

	ray_1 = new Ray(random(PI / 8, PI / 6), "#54A7A7")
	ray_2 = new Ray(-random(PI / 8, PI / 6), "#E0B479")
	ray_1.init()
	ray_2.init()

	circles = []
	numCircles = floor(0.0766 * boundary.r)
	for (let i = 0; i < numCircles; i++) {
		let phi = random(TAU)
		let r = boundary.r * 0.8 * sqrt(random())
		let c = new Circle(r * cos(phi) + w/2, r * sin(phi) + h/2)
		circles.push(c)
	}
	lines = []
	numLines = floor(0.046 * boundary.r)
	for (let i = 0; i < numLines; i++) {
		let phi = random(TAU)
		let r = boundary.r * 0.8 * sqrt(random())
		let ln = new Line(r * cos(phi) + w/2, r * sin(phi) + h/2)
		lines.push(ln)
	}

	sqiggs = []
	numSquiggs = floor(0.026 * boundary.r)
	for (let i = 0; i < numSquiggs; i++) {
		let phi = random(TAU)
		let r = boundary.r * 0.8 * sqrt(random())
		let sl = new Sqiggly(r * cos(phi) + w/2, r * sin(phi) + h/2)
		sqiggs.push(sl)
	}
}

function draw() {
	blendMode(BLEND)
    image(bgBuff, w / 2, h / 2)
	blendMode(MULTIPLY)

	ray_1.draw()
	ray_2.draw()

	circles.forEach(circle => {
		circle.update()
		circle.draw()
	})

	lines.forEach(line => {
		line.draw()
	})

	sqiggs.forEach(sqiggly => {
		sqiggly.draw()
	})

	boundary.draw()
}

function gorillaGrain(gA, buffer) {
    buffer.loadPixels();
    let d = pixelDensity();
    let halfImage = 4 * (w * d) * (h * d);
    for (let i = 0; i < halfImage; i += 4) {
      grainAmount = map(random(), 0, 1, -gA, gA);
      buffer.pixels[i] = buffer.pixels[i] + gA / 2;
      buffer.pixels[i + 1] = buffer.pixels[i + 1] + grainAmount;
      buffer.pixels[i + 2] = buffer.pixels[i + 2] + grainAmount;
      buffer.pixels[i + 3] = buffer.pixels[i + 3] + grainAmount;
    }
    buffer.updatePixels();
}


